//! `yaml.safe_load` parity: every case of tests/fixtures/evaluator/yaml_golden.json (generated by PyYAML itself with
//! gen_yaml_golden.py next to it) must give the same object or the same error (class, str(e), problem, line).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use nemo_console::services::pyfmt::float_repr;
use nemo_console::services::pyobj::{Doc, Obj, Py};
use nemo_console::services::pyyaml::{YamlError, safe_load};
use serde_json::{Value, json};

fn enc(doc: &Doc, v: &Py, active: &mut Vec<usize>) -> Value {
    match v {
        Py::None => json!(["N"]),
        Py::Bool(b) => json!(["B", b]),
        Py::Int(i) => json!(["I", doc.repr(v).unwrap_or_else(|_| format!("{i:?}"))]),
        Py::Float(f) => json!(["F", float_repr(*f)]),
        Py::Str(s) => json!(["S", s]),
        Py::Bytes(b) => json!(["Y", hex::encode(b)]),
        Py::DateTime(_) => json!(["T", doc.repr(v).unwrap(), doc.str_of(v).unwrap()]),
        Py::Date(_) => json!(["D", doc.repr(v).unwrap(), doc.str_of(v).unwrap()]),
        Py::Tuple(t) => json!([
            "U",
            t.iter().map(|x| enc(doc, x, active)).collect::<Vec<_>>()
        ]),
        Py::List(id) | Py::Dict(id) | Py::Set(id) => {
            if active.contains(id) {
                return json!(["R"]);
            }
            active.push(*id);
            let out = match &doc.objs[*id] {
                Obj::List(items) => {
                    json!([
                        "L",
                        items
                            .iter()
                            .map(|x| enc(doc, x, active))
                            .collect::<Vec<_>>()
                    ])
                }
                Obj::Dict(items) => json!([
                    "M",
                    items
                        .iter()
                        .map(|(k, x)| json!([enc(doc, k, active), enc(doc, x, active)]))
                        .collect::<Vec<_>>()
                ]),
                Obj::Set(items) => {
                    let mut e: Vec<Value> = items.iter().map(|x| enc(doc, x, active)).collect();
                    e.sort_by_key(|x| serde_json::to_string(x).unwrap());
                    json!(["E", e])
                }
            };
            active.pop();
            out
        }
    }
}

/// Python's json.dumps of the set encoding sorts by `json.dumps(e)` (", " separators): compare sorted sets loosely.
fn normalise(v: &Value) -> Value {
    match v {
        Value::Array(a) if a.first() == Some(&json!("E")) => {
            let mut items: Vec<Value> = a[1].as_array().unwrap().iter().map(normalise).collect();
            items.sort_by_key(|x| serde_json::to_string(x).unwrap());
            json!(["E", items])
        }
        Value::Array(a) => Value::Array(a.iter().map(normalise).collect()),
        other => other.clone(),
    }
}

fn err_json(e: &YamlError) -> Value {
    json!({
        "class": e.class(),
        "text": e.text(),
        "problem": e.problem(),
        "line": e.problem_mark().map(|m| m.line),
        "yaml": e.is_yaml(),
    })
}

#[test]
fn test_safe_load_matches_pyyaml_goldens() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/evaluator/yaml_golden.json"
    );
    let golden: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let cases = golden["cases"].as_array().unwrap();
    let mut failures = Vec::new();
    for c in cases {
        let input = c["input"].as_str().unwrap();
        let got = match safe_load(input) {
            Ok(doc) => json!({ "ok": normalise(&enc(&doc, &doc.root, &mut Vec::new())) }),
            Err(e) => json!({ "err": err_json(&e) }),
        };
        let mut want = c.clone();
        want.as_object_mut().unwrap().remove("input");
        if let Some(ok) = want.get("ok").cloned() {
            want["ok"] = normalise(&ok);
        }
        if got != want {
            failures.push(format!("input {input:?}\n  want {want}\n  got  {got}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ:\n{}",
        failures.len(),
        cases.len(),
        failures
            .iter()
            .take(25)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
